import React, { useEffect, useState } from "react";
import { getMyAppointments, cancelAppointment } from "../services/appointmentService";

function MyAppointments() {
  const [appointments, setAppointments] = useState([]);

  useEffect(() => {
    fetchAppointments();
  }, []);

  const fetchAppointments = async () => {
    try {
      const res = await getMyAppointments();
      console.log("DATA:", res.data);
      setAppointments(res.data);
    } catch (error) {
      console.error("ERROR:", error);
    }
  };

  const handleCancel = async (id) => {
    try {
      await cancelAppointment(id);

      setAppointments((prev) =>
        prev.map((a) =>
          a.id === id ? { ...a, status: "CANCELLED" } : a
        )
      );
    } catch (error) {
      console.error("Cancel error:", error);
    }
  };

  return (
      <div style={styles.page}>
        <h2 style={styles.title}>📅 My Appointments</h2>

        {loading ? (
          <p style={styles.message}>Loading...</p>
        ) : appointments.length === 0 ? (
          <p style={styles.message}>No appointments found 😔</p>
        ) : (
          <div style={styles.grid}>
            {appointments.map((a) => (
              <div key={a.id} style={styles.card}>
                <div style={styles.header}>
                  <h3>{a.doctorName}</h3>
                  <span
                    style={{
                      ...styles.badge,
                      background:
                        a.status === "BOOKED" ? "#4caf50" : "#f44336",
                    }}
                  >
                    {a.status}
                  </span>
                </div>

                <p><b>Specialization:</b> {a.specialization}</p>
                <p><b>Date:</b> {a.appointmentDate}</p>
                <p><b>Time:</b> {a.timeSlot}</p>

                {a.status === "BOOKED" && (
                  <button
                    onClick={() => handleCancel(a.id)}
                    style={styles.cancelBtn}
                  >
                    Cancel Appointment
                  </button>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  const styles = {
    page: {
      padding: "30px",
      background: "#f5f7fa",
      minHeight: "100vh",
    },

    title: {
      textAlign: "center",
      marginBottom: "25px",
    },

    message: {
      textAlign: "center",
      fontSize: "18px",
      color: "#666",
    },

    grid: {
      display: "grid",
      gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))",
      gap: "20px",
    },

    card: {
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
      transition: "0.3s",
    },

    header: {
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      marginBottom: "10px",
    },

    badge: {
      padding: "5px 10px",
      borderRadius: "20px",
      color: "#fff",
      fontSize: "12px",
      fontWeight: "bold",
    },

    cancelBtn: {
      marginTop: "10px",
      width: "100%",
      padding: "10px",
      border: "none",
      borderRadius: "8px",
      background: "#f44336",
      color: "#fff",
      cursor: "pointer",
      fontWeight: "bold",
    }
}

export default MyAppointments;
